
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_lc_pbeop_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_lc_pbeop", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.170102060336182e+00, -4.087801020926611e+00, -3.972535051881125e+00, -3.812981598857377e+00, -3.595811222267230e+00, -3.307254925154344e+00, -2.936759728846501e+00, -2.483348631789581e+00, -1.963154330606806e+00, -1.410237708896202e+00, -8.747087854590093e-01, -5.544838404600522e-01, -4.675098942903292e-01, -3.548952164196092e-01, -2.086454023646742e-01, -7.786444792009053e-02, -1.257516973788672e-02, -1.025197615252850e-03, -8.375770732371568e-05, -4.518782897762689e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


